xmop Vout N006 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xmop} l={L_xmop}
xmon Vout N010 0 0 sky130_fd_pr__nfet_01v8 w={W_xmon} l={L_xmon}

* Feedback network for DC stability during AC analysis
Rf vm Vout 100MEG
Cf vm 0 10u

* AC input source at noninverting terminal
Vin vin 0 dc 0.9 ac 1.0

.control
* --- Operating Point Analysis ---
op
let pwr = -i(VDD) * 1.8
let i_mon = @m.xmon.msky130_fd_pr__nfet_01v8[id]
print pwr i_mon

* --- AC Frequency Response ---
ac dec 100 1k 1G
let gain_db = vdb(Vout)
let phase = 180/PI * cph(v(Vout))

meas ac open_loop_gain find gain_db at=1k
meas ac unity_gain_frequency when gain_db=0 fall=1
meas ac phase_at_ugf find phase when gain_db=0 fall=1
let phase_margin = 180 + phase_at_ugf
print open_loop_gain unity_gain_frequency phase_margin

* --- Transient Large-Signal Step Response (Fig. 24.31) ---
alter Rf = 10k
alter Cf = 1p
alter Vin dc = 0.5
alter @Vin[pulse] = [ 0.1 0.9 10n 100p 100p 50n 100n ]

* Add 1k resistor and 10pF load as specified in Fig. 24.31
Rload Vout 0 1k
Cload Vout 0 10p

tran 0.1n 120n
meas tran v_min min v(Vout)
meas tran v_max max v(Vout)
meas tran slew_rate_pos trig v(Vout) val=0.3 rise=1 targ v(Vout) val=0.7 rise=1
meas tran slew_rate_neg trig v(Vout) val=0.7 fall=1 targ v(Vout) val=0.3 fall=1

quit
.endc
.end

